<script lang="ts">
 import {base} from '$app/paths';import {onMount} from 'svelte';import {allCards} from '$lib/data/game';import GameCard from '$lib/components/GameCard.svelte';import Accessories from '$lib/components/Accessories.svelte';
 import {paperSizes,printSheets,cropMarks,type Paper} from '$lib/print/layout';
 let ready=$state(false);onMount(()=>ready=true);
 let paper=$state<Paper>('a4'), mono=$state(false), side=$state('both'), category=$state('all'), kit=$state('cards'), players=$state(5), backX=$state(0),backY=$state(0),preview=$state(0),printing=$state(false),error=$state(''),viewport=$state(1200);
 let dimensions=$derived(paperSizes[paper]);
 let cards=$derived(allCards.filter(c=>category==='all'||category===c.kind));
 let sheets=$derived(printSheets(cards,paper,{x:backX,y:backY}).filter(s=>side==='both'||side===s.side));
 let count=$derived(kit==='cards'?sheets.length:Math.ceil(players/2)+3);
 let pageIndex=$derived(Math.min(preview,count-1));
 let scale=$derived(Math.min(1,Math.max(0.2,(viewport-48)/(dimensions.width*96/25.4))));
 async function print(){printing=true;error='';try{document.querySelectorAll<HTMLImageElement>('.sheets img').forEach(i=>i.loading='eager');await document.fonts.ready;await Promise.all(Array.from(document.querySelectorAll<HTMLImageElement>('.sheets img')).map(i=>i.decode()));await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));window.print();}catch{error='Some artwork could not load. Reload and try again before printing.';}finally{printing=false;}}
</script>
<svelte:window bind:innerWidth={viewport}/>
<svelte:head><title>Print & play — Higher Powers</title><meta name="description" content="Print all 27 cards, matching mirrored backs, Favor tracks, special-area mats, and score sheets on A4 or US Letter. Full color and low-ink options."/></svelte:head>
<main id="main" class="print-main" data-ready={ready} style:--page-width={`${dimensions.width}mm`} style:--page-height={`${dimensions.height}mm`}>
 <div class="print-controls"><p class="eyebrow">THE HEAVENLY PRINT SHOP</p><h1>Bring Heaven to the table.</h1><p class="lead">You already have the souls. Here is the paperwork.</p><p>Use your own standard 106-tile Rummikub set and racks. Print 27 cards plus table essentials; bring an opaque bag, five coins, and pencils.</p><div class="print-options"><label>Components<select disabled={!ready||printing} bind:value={kit} onchange={()=>preview=0}><option value="cards">Cards</option><option value="accessories">Table essentials</option></select></label><label>Paper<select disabled={!ready||printing} bind:value={paper}><option value="a4">A4</option><option value="letter">US Letter</option></select></label><label>Artwork<select disabled={!ready||printing} bind:value={mono}><option value={false}>Full color</option><option value={true}>Low ink</option></select></label>{#if kit==='cards'}<label>Collection<select disabled={!ready||printing} bind:value={category} onchange={()=>preview=0}><option value="all">All 27 cards</option><option value="angel">12 Angels</option><option value="decree">10 Decrees</option><option value="judgment">5 Judgments</option></select></label><label>Print sides<select disabled={!ready||printing} bind:value={side} onchange={()=>preview=0}><option value="both">Fronts & backs</option><option value="front">Fronts only</option><option value="back">Backs only</option></select></label>{:else}<label>Players<select disabled={!ready||printing} bind:value={players} onchange={()=>preview=0}><option value={3}>3</option><option value={4}>4</option><option value={5}>5</option></select></label>{/if}</div>
 {#if kit==='cards'}<details class="registration"><summary>Adjust double-sided alignment</summary><p>Print pages 1–2 first. Hold them to the light. Directions refer to the back as you look at it. If marks are too far right, use a negative horizontal offset; too low, use a negative vertical offset.</p><div class="print-options"><label>Back horizontal offset (mm)<input disabled={!ready||printing} type="number" min="-2" max="2" step="0.1" bind:value={backX}/></label><label>Back vertical offset (mm)<input disabled={!ready||printing} type="number" min="-2" max="2" step="0.1" bind:value={backY}/></label></div><button onclick={()=>{backX=0;backY=0;}}>Reset alignment</button></details>{/if}
 <div class="print-instructions"><h2>Print at actual size</h2><ol><li>Choose the same paper size here and in your print dialog. Use portrait, <strong>100% / actual size</strong>, no browser headers or footers.</li><li>Enable background graphics for full color. Low ink uses plain fronts with black text and grayscale painted backs.</li>{#if kit==='cards'}<li>Cards are <strong>63 × 88 mm</strong>, nine per sheet. For both sides, use <strong>long-edge duplex</strong>; pages alternate fronts and mirrored backs. Test the first pair before printing all six pages.</li><li>Cut along the crop marks. Sleeve with spare backing cards if your paper is thin. Matching category backs conceal card identities.</li>{:else}<li>Print table essentials single-sided. Cut the Favor tracks apart; place coins on them. Two region mats allow both Sanctuary Angels to play together. Cut areas apart and use only those needed.</li>{/if}</ol><p>On US Letter, the nine-card grid leaves 7.7 mm top/bottom margins. Do not use “fit to page.” Small printer registration errors are expected; test before cutting.</p></div>
 <div class="print-actions"><button class="button primary" onclick={print} disabled={!ready||printing}>{printing?'Preparing artwork…':'Print / save PDF'}</button><span role="status">{kit==='cards'?`${cards.length} cards · `:''}{count} pages</span></div>{#if error}<p role="alert">{error}</p>{/if}
 <details class="download-options"><summary>Download ready-made PDFs</summary><p>Complete 27-card decks, with matching backs:</p><div class="download-grid">{#each ['a4','letter'] as size}{#each ['color','low-ink'] as style}<a href={`${base}/downloads/higher-powers-cards-${size}-${style}.pdf`} download>{size==='a4'?'A4':'US Letter'} · {style==='color'?'full color':'low ink'}</a>{/each}<a href={`${base}/downloads/higher-powers-accessories-${size}.pdf`} download>{size==='a4'?'A4':'US Letter'} · table essentials for five</a>{/each}</div><p><a href={`${base}/downloads/higher-powers-cards-a4-fronts.pdf`} download>A4 · full-color fronts only</a></p><p><a href={`${base}/downloads/higher-powers-rulebook.pdf`} download>Illustrated rulebook · A4</a> · <a href={`${base}/downloads/higher-powers-rulebook-letter.pdf`} download>US Letter</a></p></details>
 <nav class="preview-nav" aria-label="Print preview"><button disabled={pageIndex===0} onclick={()=>preview=pageIndex-1}>Previous</button><span>Page {pageIndex+1} of {count}{kit==='cards'?` · ${sheets[pageIndex]?.side==='front'?'Fronts':'Backs'}`:''}</span><button disabled={pageIndex>=count-1} onclick={()=>preview=pageIndex+1}>Next</button></nav></div>
 <div class="print-preview" style:width={`${dimensions.width}mm`} style:height={`${dimensions.height*96/25.4*scale}px`}><div class="sheets" class:low-ink={mono} data-paper={paper} data-kit={kit} style:zoom={scale}>
 {#if kit==='cards'}{#each sheets as sheet,i}<section class="print-sheet" class:current={i===pageIndex} data-side={sheet.side} aria-label={`Sheet ${sheet.number}, ${sheet.side}`}>
 {#each sheet.cards as item}<div class="print-card" style:left={`${item.x}mm`} style:top={`${item.y}mm`}><GameCard card={item.card} back={sheet.side==='back'} {mono}/></div>{/each}
 <svg class="crop-marks" viewBox={`0 0 ${dimensions.width} ${dimensions.height}`} aria-label="Cutting guides" role="img">{#each cropMarks(sheet) as mark}<line {...mark}/>{/each}</svg><p class="sheet-label">HIGHER POWERS · SHEET {sheet.number} · {sheet.side.toUpperCase()} · 63 × 88 mm · {dimensions.label} · 100% · LONG-EDGE DUPLEX</p></section>{/each}
 {:else}{#each Array(Math.ceil(players/2)+3) as _,i}<section class="print-sheet accessory-sheet" class:current={i===pageIndex}>{#if i<Math.ceil(players/2)}<Accessories type="favor"/>{#if i*2+1<players}<Accessories type="favor"/>{/if}{:else if i<Math.ceil(players/2)+2}<Accessories type="zones"/>{:else}<Accessories type="score"/>{/if}<p class="sheet-label">HIGHER POWERS · TABLE ESSENTIALS · {dimensions.label} · 100% · SINGLE-SIDED</p></section>{/each}{/if}
 </div></div>
</main>
